<?php require_once '../includes/auth.php';require_once '../config/koneksi.php';$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT * FROM jenis_pembayaran WHERE id_jenis=?');$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();if(!$row){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama_jenis']??'');$nom=(float)($_POST['nominal']??0);$tingkat=$_POST['tingkat']??'Semua Tingkat';$ket=trim($_POST['keterangan']??'');$status=$_POST['status']??'aktif';if($nama===''||$nom<0||!in_array($tingkat,['Semua Tingkat','VII','VIII','IX'],true)||!in_array($status,['aktif','nonaktif'],true)){$error='Periksa kembali data yang dimasukkan.';$row=array_merge($row,$_POST);}else{$st=$conn->prepare('UPDATE jenis_pembayaran SET nama_jenis=?,tingkat=?,nominal=?,keterangan=?,status=? WHERE id_jenis=?');$st->bind_param('ssdssi',$nama,$tingkat,$nom,$ket,$status,$id);$st->execute();header('Location: index.php');exit;}}$page_title='Edit Jenis Pembayaran';$active='jenis';$prefix='../';include '../includes/header.php';?><div class="page-heading"><div><h1>Edit Jenis Pembayaran</h1><p>Perbarui kategori biaya dan tingkat yang dikenai.</p></div><a href="index.php" class="btn btn-light border">Kembali</a></div><div class="panel"><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama Jenis *</label><input name="nama_jenis" class="form-control" required value="<?= e($row['nama_jenis']) ?>"></div><div class="col-md-6"><label class="form-label">Nominal Standar (Rp) *</label><input type="number" min="0" step="1" name="nominal" class="form-control" required value="<?= e($row['nominal']) ?>"></div><div class="col-md-6"><label class="form-label">Berlaku untuk Tingkat *</label><select name="tingkat" class="form-select"><?php foreach(['Semua Tingkat','VII','VIII','IX'] as $t):?><option value="<?= e($t) ?>" <?= ($row['tingkat']??'Semua Tingkat')===$t?'selected':'' ?>><?= $t==='Semua Tingkat'?'Semua Tingkat SMP':'Kelas '.$t ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="aktif" <?= $row['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="nonaktif" <?= $row['status']==='nonaktif'?'selected':'' ?>>Nonaktif</option></select></div><div class="col-12"><label class="form-label">Keterangan</label><textarea name="keterangan" class="form-control" rows="3"><?= e($row['keterangan']??'') ?></textarea></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary">Simpan Perubahan</button><a href="index.php" class="btn btn-light border">Batal</a></div></form></div></div><?php include '../includes/footer.php';?>